package com.vaijunto.service;
import com.vaijunto.domain.entities.*; import com.vaijunto.exception.ApiException; import com.vaijunto.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*;
@Service @RequiredArgsConstructor public class BlockService { private final UserRepository users; private final UserBlockRepository blocks; private final ConversationRepository conversations; private final TripPassengerRepository passengers;
 @Transactional public void block(UUID targetId,String email){var actor=user(email);var target=users.findById(targetId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"USER_NOT_FOUND","Usuário não encontrado."));if(actor.getId().equals(targetId))throw new ApiException(HttpStatus.BAD_REQUEST,"BLOCK_INVALID","Você não pode bloquear a si mesmo.");UUID low=actor.getId().compareTo(targetId)<0?actor.getId():targetId, high=low.equals(actor.getId())?targetId:actor.getId();if(!blocks.existsByUserLowIdAndUserHighId(low,high))blocks.save(UserBlock.builder().userLow(low.equals(actor.getId())?actor:target).userHigh(high.equals(actor.getId())?actor:target).build());passengers.findByTripInstanceDriverIdAndPassengerIdAndStatusIn(actor.getId(),targetId,List.of(com.vaijunto.domain.enums.PassengerStatus.CONFIRMED,com.vaijunto.domain.enums.PassengerStatus.CHECKED_IN)).forEach(p->p.setStatus(com.vaijunto.domain.enums.PassengerStatus.CANCELLED));passengers.findByTripInstanceDriverIdAndPassengerIdAndStatusIn(targetId,actor.getId(),List.of(com.vaijunto.domain.enums.PassengerStatus.CONFIRMED,com.vaijunto.domain.enums.PassengerStatus.CHECKED_IN)).forEach(p->p.setStatus(com.vaijunto.domain.enums.PassengerStatus.CANCELLED));conversations.findBetween(actor.getId(),targetId).forEach(c->{c.setArchivedAt(OffsetDateTime.now());c.setReadOnlyAt(OffsetDateTime.now());}); }
 @Transactional public void unblock(UUID targetId,String email){var actor=user(email);UUID low=actor.getId().compareTo(targetId)<0?actor.getId():targetId, high=low.equals(actor.getId())?targetId:actor.getId();blocks.findByUserLowIdAndUserHighId(low,high).ifPresent(blocks::delete);}
 @Transactional(readOnly=true) public List<com.vaijunto.dto.BlockUserDto> list(String email){var actor=user(email);return blocks.findForUser(actor.getId()).stream().map(b->{var other=b.getUserLow().getId().equals(actor.getId())?b.getUserHigh():b.getUserLow();return new com.vaijunto.dto.BlockUserDto(other.getId(),other.getName());}).toList();} public boolean blocked(UUID a,UUID b){return blocks.existsBetween(a,b);} private User user(String email){return users.findByEmail(email).orElseThrow(ApiException::userNotFound);} }
